import re
BASE = 'https://app.leg.wa.gov'
def page(url):
    kind, body = fetch(url)
    return body if isinstance(body, str) else body.decode('utf-8', 'ignore')
def cites(body, pat):
    out = []
    for h in re.findall(r'href=["\']([^"\']+)', body.replace('&amp;', '&'), re.I):
        m = re.search(r'cite=(' + pat + r')$', h, re.I)
        if m and m.group(1) not in out:
            out.append(m.group(1))
    return out
def sections():
    titles = cites(page(BASE + '/RCW/default.aspx'), r'\d+[A-Z]?')         # every title, 28A and 35A included
    log('titles: ' + str(len(titles)))
    seen = set()
    for t in titles:
        try:
            chapters = cites(page(BASE + '/RCW/default.aspx?cite=' + t), r'\d+[A-Z]?\.\d+[A-Z]?')
        except Exception as e:
            log('title failed ' + t + ' ' + repr(e)); continue
        for ch in chapters:
            try:
                secs = cites(page(BASE + '/RCW/default.aspx?cite=' + ch), r'\d+[A-Z]?\.\d+[A-Z]?\.\d+[A-Z]?')
            except Exception as e:
                log('chapter failed ' + ch + ' ' + repr(e)); continue
            for sid in secs:
                if sid in seen:
                    continue
                seen.add(sid)
                url = BASE + '/RCW/default.aspx?cite=' + sid
                try:
                    body = page(url)
                except Exception as e:
                    log('section failed ' + sid + ' ' + repr(e)); continue
                text = block_text(body, id='contentWrapper')                 # the section's own words and its history
                h2 = re.search(r'(?is)<h2>(.*?)</h2>', body)
                heading = re.sub(r'\s+', ' ', re.sub(r'<[^>]+>', ' ', h2.group(1))).strip() if h2 else ''
                if text:
                    yield {'id': sid, 'heading': heading.replace(' — ', '—'), 'text': text, 'url': url}
